def M(id,title,obj,res,je=None,assess=None,mins=None):
    return dict(id=id,title=title,objectives=obj,resources=res,joyful=je,assessment=assess or 'Complete the linked activities and the self-check at the end of the module.',time=mins or 'about 2–3 hours')
