cat={r['resource_id'] for r in json.load(open(sys.argv[1]+'/catalog.json'))}
missing=[(s['id'],m['id'],r) for s in ST for m in s['modules'] for r in m['resources'] if r not in cat]
assert not missing,missing
MAP=[{'cefr':'Pre-A1','grades':'Grades 1–2','joyful':'Level 1','stage':'0–1'},{'cefr':'A1','grades':'Grades 3–4','joyful':'Level 2','stage':'2'},{'cefr':'A2','grades':'Grades 5–8','joyful':'Levels 3–4','stage':'2'},{'cefr':'B1','grades':'Grades 9–10','joyful':'Levels 5–6','stage':'3'},{'cefr':'B2','grades':'Grades 11–12, university entry','joyful':'Level 7','stage':'4'},{'cefr':'C1','grades':'University, professional','joyful':'Level 8','stage':'5'},{'cefr':'C2','grades':'Specialist','joyful':'—','stage':'6'}]
open(sys.argv[1]+'/curriculum.js','w').write('/* Joyful English Web Book: curriculum blueprint (generated) */\nwindow.CURRICULUM='+json.dumps({'stages':ST,'map':MAP},ensure_ascii=False,separators=(',',':'))+';\n')
json.dump({'stages':ST,'map':MAP},open(sys.argv[1]+'/curriculum.json','w'),ensure_ascii=False,indent=1)
